require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/resend.php';send_cors_headers();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);$body=get_json_body();$email=strtolower(trim((string)($body['email']??'')));$type=trim((string)($body['account_type']??'customer'));if(!is_valid_email($email)||!in_array($type,['customer','vendor','influencer'],true))json_response(422,['success'=>false,'message'=>'Enter a valid account email.']);if(rate_limit('password-reset|'.$email.'|'.request_ip(),5,3600))json_response(429,['success'=>false,'message'=>'Too many reset attempts. Try again later.']);$map=['customer'=>['users','email_verified'],'vendor'=>['vendors','email_verified'],'influencer'=>['influencers','email_verified']];[$table,$verified]=$map[$type];$stmt=get_db()->prepare("SELECT id,{$verified} verified FROM {$table} WHERE email=:email LIMIT 1");$stmt->execute(['email'=>$email]);$account=$stmt->fetch();if($account&&$account['verified']){$raw=rtrim(strtr(base64_encode(random_bytes(48)),'+/','-_'),'=');$id=uuid_string();get_db()->prepare('UPDATE password_reset_tokens SET used_at=UTC_TIMESTAMP() WHERE principal_type=:type AND principal_id=:owner AND used_at IS NULL')->execute(['type'=>$type,'owner'=>$account['id']]);get_db()->prepare('INSERT INTO password_reset_tokens (id,principal_type,principal_id,token_hash,created_at,expires_at) VALUES (:id,:type,:owner,:hash,UTC_TIMESTAMP(),DATE_ADD(UTC_TIMESTAMP(),INTERVAL 30 MINUTE))')->execute(['id'=>$id,'type'=>$type,'owner'=>$account['id'],'hash'=>hash_hmac('sha256',$raw,APP_KEY)]);$url=(APP_URL!==''?APP_URL:request_origin()).'/frontend/reset-password.php?token='.rawurlencode($raw).'&type='.rawurlencode($type);resend_send_email($email,'Reset your Conscious Indi password','<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;padding:32px"><h2>Reset your password</h2><p>This secure link expires in 30 minutes and can be used once.</p><p><a href="'.htmlspecialchars($url,ENT_QUOTES,'UTF-8').'">Reset password</a></p><p>If you did not request this, ignore this email.</p></div>');}json_response(200,['success'=>true,'message'=>'If the account exists, a password reset link has been sent.']);
